func (c *checker) reportCheckedCall(call *syntax.Expression) {
	model := c.checkedCall(call)
	if model == nil {
		return
	}
	c.reportModelResult(syntax.ExpressionPosition(call), model,
		"tgo %s %s result error must be checked or returned",
		modelKind(model), modelName(model))
}
